import {pinyin} from './vendor/pinyin-pro.mjs';
import {previewCsv} from './import-preview.mjs';
const root=document.querySelector('#app'),dialog=document.querySelector('#dialog');
const platformAuth = import(new URL('../workbench/platform-auth.mjs?v=20261115-polish', import.meta.url)).catch(()=>null);
const prefix=location.pathname.includes('/miniapp/')?'/miniapp':'',base=prefix+'/api/collaboration';
let codeState=null,projectListReturn=null;
let unreadCount=0,unreadNext=0,unreadRequest=null,developmentNext=0,refreshTimer;
let me=null,people=[],projects=[],current=null,handlers=new Map(),sequence=0,epoch=0,noticeTimer,developmentFingerprint='',pollingDevelopment=false;
const labels={planned:'待开始',active:'进行中',in_progress:'开发中',blocked:'有阻塞',review:'待确认',done:'已完成',completed:'已完成',archived:'已归档',superseded:'已有新提交',queued:'排队中',running:'检查中',passed:'检查通过',previewed:'可预览',tested:'可验收',failed:'失败',requested:'待管理员发布',publishing:'发布中',published:'已发布',open:'待审核',closed:'已关闭',merged:'已合并',pending:'同步中',ready:'已连接',retrying:'正在重试'};
export const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e=escape,token=()=>sessionStorage.getItem('siyue_web_token')||'',name=id=>people.find(p=>p.id===id)?.name||'待补充';
const plain=s=>String(s??'').replace(/@\[([^\]]+)\]\(staff:[0-9a-f-]{36}\)/gi,'@$1');
const rich=s=>e(s).replace(/@\[([^\]]+)\]\(staff:([0-9a-f-]{36})\)/gi,'<span class="mention">@$1</span>');
const date=s=>s?new Date(s).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}):'待补充';
const badge=s=>`<span class="badge ${e(s)}">${e(labels[s]||s)}</span>`;
const flask='<svg class="flask" viewBox="0 0 24 24" aria-hidden="true"><path d="M9 3h6M10 3v6L4.5 19a1.3 1.3 0 0 0 1.2 2h12.6a1.3 1.3 0 0 0 1.2-2L14 9V3M7.5 14h9" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg>';
const ownerLabel=p=>p.ownerTeam||name(p.ownerId);
const teamOwner=p=>p.ownerTeam?`<span class="person team-owner">${flask}${e(p.ownerTeam)}</span>`:person(p.ownerId);
const taskOwner=t=>t?.ownerId?person(t.ownerId):teamOwner(current.project);
const person=id=>`<span class="person"><span class="avatar">${e(name(id).slice(-2))}</span>${e(name(id))}</span>`;
const on=fn=>{const id=String(++sequence);handlers.set(id,fn);return id;};
const button=(label,fn,cls='')=>`<button type="button" class="${cls}" data-action="${on(fn)}">${label}</button>`;
const route=()=>{const [page='projects',query='']=location.hash.slice(1).split('?');return {page:page||'projects',...Object.fromEntries(new URLSearchParams(query))};};
const go=(page,args={})=>{const hash='#'+page+(Object.keys(args).length?'?'+new URLSearchParams(args):'');if(location.hash===hash)void render();else{root.inert=true;location.hash=hash;}};
const projectGo=(id,tab='tasks',view='list',extra={})=>go('project',{id,tab,view,...extra});
function toast(message){const node=document.querySelector('#toast');node.textContent=message;node.hidden=false;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>node.hidden=true,4500);}
async function api(path,method='GET',body){
 const response=await fetch(base+path,{method,headers:{Authorization:'Bearer '+token(),...(body instanceof FormData?{}:{'Content-Type':'application/json'})},body:body==null?undefined:body instanceof FormData?body:JSON.stringify(body),cache:'no-store',signal:AbortSignal.timeout(35000)});
 const value=response.status===204?null:await response.json().catch(()=>null);if(!response.ok){if(response.status===401){sessionStorage.removeItem('siyue_web_token');me=null;}throw Object.assign(new Error(value?.message||'服务暂时不可用'),{status:response.status});}return value;
}
async function run(fn){try{await fn();}catch(error){if(error.status===401){login();return;}const box=dialog.open?dialog.querySelector('.error'):null;if(box)box.textContent=error.message;else toast(error.message);}}
document.addEventListener('keydown',ev=>{if((ev.key==='Enter'||ev.key===' ')&&ev.target.matches('tr[data-action]')){ev.preventDefault();ev.target.click();}});
document.addEventListener('click',ev=>{const b=ev.target.closest('[data-action]');if(b&&!b.disabled){ev.preventDefault();const fn=handlers.get(b.dataset.action);if(fn){b.disabled=true;void run(()=>fn(b)).finally(()=>b.disabled=false);}}});
function shell(html){
 const r=route(),active=['projects','project'].includes(r.page),pageTitle=current?.project?.name||(r.page==='todos'?'我的待办':r.page==='notifications'?'站内通知':'所有项目');
 root.innerHTML=`<div class="layout collaboration-workspace"><header class="app-header compact-header"><div class="collab-breadcrumb"><a href="#projects">项目协作</a><span aria-hidden="true">/</span><span title="${e(pageTitle)}">${e(pageTitle)}</span></div><nav class="main-nav" aria-label="项目协作导航"><a href="#projects" class="${active?'active':''}" ${active?'aria-current="page"':''}>项目</a><a href="#todos" class="${r.page==='todos'?'active':''}" ${r.page==='todos'?'aria-current="page"':''}>我的待办</a><a href="#notifications" class="${r.page==='notifications'?'active':''}">站内通知 <span id="unread"></span></a></nav><div class="header-account"><span>${e(me.user.name)}</span>${button('WorkBuddy 接入',()=>agentDialog(current?.project?.id),'text-button')}</div></header><main>${html}</main></div>`;
 paintUnread();void unread();
}
function heading(title,desc,actions=''){return `<div class="heading"><div><h1>${e(title)}</h1><p>${e(desc)}</p></div><div class="actions">${actions}</div></div>`;}
function empty(text){return `<div class="empty">${e(text)}</div>`;}
function modal(title,html,{drawer=false}={}){dialog.classList.toggle('collaboration-drawer',drawer);dialog.setAttribute('aria-labelledby','collab-dialog-title');dialog.innerHTML=`<div class="heading"><h2 id="collab-dialog-title">${e(title)}</h2>${button('关闭',()=>dialog.close(),'dialog-close')}</div><div class="dialog-content"><div class="error" role="alert"></div>${html}</div>`;if(!dialog.open)dialog.showModal();}
dialog.addEventListener('close',()=>{if(dialog.open)return;const r=route();if(r.target){delete r.target;const page=r.page;delete r.page;history.replaceState(null,'','#'+page+(Object.keys(r).length?'?'+new URLSearchParams(r):''));}if(current&&root.querySelector('.task-workspace'))paintTasks();});
function bindForm(fn){const form=dialog.querySelector('form');form.addEventListener('submit',ev=>{ev.preventDefault();const submit=form.querySelector('[type=submit]');submit.disabled=true;void run(()=>fn(Object.fromEntries(new FormData(form)),form)).finally(()=>submit.disabled=false);});}
function field(label,key,value='',type='text',required=false){return `<label class="field">${e(label)}<input type="${type}" name="${key}" value="${e(value)}" ${key==='account'?'autocomplete="username"':key==='password'?'autocomplete="current-password"':''} ${required?'required':''}></label>`;}
function textField(label,key,value='',required=false){return `<label class="field full">${e(label)}<textarea name="${key}" data-mentions ${required?'required':''}>${e(value)}</textarea><span class="help">输入 @ 提及同事</span></label>`;}
function selectField(label,key,options,selected){return `<label class="field">${e(label)}<select name="${key}">${options.map(([v,l])=>`<option value="${e(v)}" ${v===selected?'selected':''}>${e(l)}</option>`).join('')}</select></label>`;}
const formEnd=(label='保存',cancel=()=>dialog.close())=>`</div><div class="form-actions">${button('取消',cancel)}<button class="primary" type="submit">${label}</button></div></form>`;
function memberOptions(){return current?current.members.map(m=>[m.staffId,name(m.staffId)]):people.map(p=>[p.id,p.name+' · '+p.department]);}
function searchable(p,q){const needle=q.trim().toLowerCase();return !needle||[p.name,p.account,p.department,p.pinyin,p.initials].some(v=>String(v).toLowerCase().includes(needle));}
function peopleRows(q,select){return people.filter(p=>searchable(p,q)).slice(0,60).map(p=>button(`<span class="avatar">${e(p.name.slice(-2))}</span><span>${e(p.name)}<small>${e(p.department)} · ${e(p.account||'未设置账号')}</small></span><span>${current?.members.some(m=>m.staffId===p.id)?'已加入':'选择'}</span>`,()=>select(p))).join('')||empty('没有找到同事');}
function choosePerson(title,fn){modal(title,`<input class="search" id="person-search" placeholder="搜索姓名、拼音、部门" autofocus><div class="people-list" id="people-results"></div>`);const list=dialog.querySelector('#people-results');const paint=q=>list.innerHTML=peopleRows(q,fn);paint('');dialog.querySelector('#person-search').oninput=ev=>paint(ev.target.value);}
function mentions(form,projectId){
 for(const input of form.querySelectorAll('[data-mentions]')){
  const mapping=new Map();input.value=input.value.replace(/@\[([^\]]+)\]\(staff:([0-9a-f-]{36})\)/gi,(_,label,id)=>{const p=people.find(p=>p.id===id),display='@'+label+(p?.account?'（'+p.account+'）':'');mapping.set(display,{id,label});return display;});input.mentionMap=mapping;
  input.addEventListener('input',()=>{
   form.querySelectorAll('.mention-popup').forEach(x=>x.remove());const before=input.value.slice(0,input.selectionStart);const match=before.match(/@([^@\s（）]{0,25})$/);if(!match)return;
   const start=input.selectionStart-match[0].length,end=input.selectionStart;const popup=document.createElement('div');popup.className='mention-popup';popup.setAttribute('role','listbox');
   for(const p of people.filter(p=>searchable(p,match[1])).sort((a,b)=>Number(current?.members.some(m=>m.staffId===b.id))-Number(current?.members.some(m=>m.staffId===a.id))).slice(0,10)){
    const row=document.createElement('button');row.type='button';row.setAttribute('role','option');row.setAttribute('aria-selected','false');row.onmousedown=ev=>ev.preventDefault();row.innerHTML=`${e(p.name)}<small>${e(p.department)} · ${e(p.account)}${projectId&&!current?.members.some(m=>m.staffId===p.id)?' · 尚未加入项目':''}</small>`;
    row.onclick=()=>{const display='@'+p.name+(p.account?'（'+p.account+'）':'');mapping.set(display,{id:p.id,label:p.name});input.setRangeText(display+' ',start,end,'end');popup.remove();input.focus();
     if(projectId&&(!current.project.confidential||current.canManage)&&!current?.members.some(m=>m.staffId===p.id)){const add=document.createElement('button');add.type='button';add.textContent='添加 '+p.name+' 为协作者并通知';add.onclick=()=>void run(async()=>{await api(`/projects/${projectId}/members`,'POST',{staffId:p.id});current.members.push({staffId:p.id,role:'contributor'});add.remove();toast('已添加协作者');});input.parentElement.append(add);}
    };popup.append(row);
   }if(popup.children.length)input.parentElement.append(popup);
  });input.addEventListener('keydown',ev=>{const popup=input.parentElement.querySelector('.mention-popup');if(!popup)return;if(ev.key==='Escape'){popup.remove();return;}const rows=[...popup.querySelectorAll('button')];if(['ArrowDown','ArrowUp'].includes(ev.key)){ev.preventDefault();const index=rows.findIndex(r=>r.getAttribute('aria-selected')==='true'),next=ev.key==='ArrowDown'?(index+1)%rows.length:(index<0?rows.length-1:(index-1+rows.length)%rows.length);rows.forEach((r,i)=>r.setAttribute('aria-selected',String(i===next)));rows[next]?.scrollIntoView({block:'nearest'});}else if(ev.key==='Enter'){ev.preventDefault();(rows.find(r=>r.getAttribute('aria-selected')==='true')||rows[0])?.click();}});
 }
}
function encodeMentions(form,key,value){let s=value||'';for(const [display,p] of form.elements[key]?.mentionMap||[])s=s.split(display).join(`@[${p.label}](staff:${p.id})`);return s;}
async function initialize(){if(me)return;me=await api('/me');await api('/session','POST',{});const loaded=await api('/people');people=loaded.map(p=>({...p,pinyin:pinyin(p.name,{toneType:'none',separator:''}),initials:pinyin(p.name,{pattern:'first',toneType:'none',separator:''})}));}
function login(){unreadRequest=null;unreadCount=0;unreadNext=0;clearTimeout(refreshTimer);root.innerHTML=`<div class="login"><div class="brand">思跃 · 项目协作</div><h1>用工作台账号登录</h1><form>${field('账号','account','','text',true)}${field('密码','password','','password',true)}<div class="error" role="alert"></div><button class="primary" type="submit">登录</button><a href="${prefix}/workbench/">返回教学工作台</a><a href="./agent/">Workbuddy / Agent 操作说明</a></form></div>`;const form=root.querySelector('form');form.onsubmit=async ev=>{ev.preventDefault();const b=form.querySelector('button');b.disabled=true;try{const data=Object.fromEntries(new FormData(form));const r=await fetch(prefix+'/api/auth/password',{method:'POST',headers:{'Content-Type':'application/json',...(await platformAuth)?.browserSessionHeaders},body:JSON.stringify(data)});const result=await r.json();if(!r.ok)throw Error(result.message||'登录失败');const auth=await platformAuth;if(auth)auth.updateBrowserSession(result.token);else sessionStorage.setItem('siyue_web_token',result.token);await render();}catch(e){form.querySelector('.error').textContent=e.message;}finally{b.disabled=false;}};}
async function render({navigation=false}={}){const next=route();const workspace=root.querySelector('.task-workspace');if(navigation&&token()&&current&&workspace&&!root.hasAttribute('aria-busy')&&next.page==='project'&&next.id===current.project.id&&!['code','development','releases'].includes(next.tab)&&!next.target){for(const node of workspace.querySelectorAll('[data-action]'))handlers.delete(node.dataset.action);workspace.outerHTML=tasksView();bindTaskViews();root.inert=false;return;}const ticket=++epoch;if(!token()){root.inert=false;login();return;}root.inert=true;root.setAttribute('aria-busy','true');try{
 await initialize();if(ticket!==epoch)return;const auth=new URLSearchParams(location.search).get('authorize');if(auth){const target=new URL(auth,location.origin);if(target.origin!==location.origin||target.pathname!==prefix+'/api/collaboration/oidc/authorize')throw Error('授权地址无效');current=null;shell(heading('连接代码平台','继续使用当前工作台身份登录代码平台。')+`<div class="panel"><p>${person(me.user.id)}</p>${button('使用此账号继续',async()=>{await api('/session','POST',{});location.assign(target.href);},'primary')}</div>`);return;}
 const r=route();handlers.clear();current=null;if(r.page==='project'){current=await api('/projects/'+r.id);if(ticket!==epoch)return;await projectPage(r);}
 else if(r.page==='notifications')await notificationPage();else if(r.page==='todos')await todoPage();else await projectList();
 }catch(error){if(error.status===401){login();return;}if(error.status===428){const auth=await platformAuth;if(auth){auth.returnToWorkbenchForPassword();return;}}root.innerHTML=`<div class="login"><h2>暂时无法打开</h2><p class="error">${e(error.message)}</p><a href="#projects">返回项目列表</a> · <a href="${prefix}/workbench/">教学工作台</a></div>`;}finally{if(ticket===epoch){root.inert=false;root.removeAttribute("aria-busy");scheduleRefresh();}}}
function paintUnread(){const badge=document.querySelector('#unread');if(badge)badge.textContent=unreadCount||'';}
async function unread(){
 if(document.body.hasAttribute('data-platform-inbox')||!token()||document.hidden||unreadRequest||performance.now()<unreadNext)return;
 unreadNext=performance.now()+30000;
 const request=api('/notifications/unread-count');
 unreadRequest=request;
 try{const {count}=await request;if(unreadRequest===request){unreadCount=count;paintUnread();}}catch{}
 finally{if(unreadRequest===request)unreadRequest=null;scheduleRefresh();}
}
function rememberUnread(rows){
 unreadRequest=null;
 unreadCount=rows.filter(n=>!n.readAt).length;
 unreadNext=performance.now()+30000;
}
async function markRead(id){
 await api(`/notifications/${id}/read`,'POST',{});
 unreadRequest=null;unreadNext=0;
 window.dispatchEvent(new CustomEvent('siyue:inbox-change',{detail:'collaboration'}));
}
async function projectList(){
 projects=await api('/projects');const filter=route().filter==='mine'?'lab':route().filter||'lab';
 shell(`${route().repository?'<div class="repository-filter">'+e(route().repository)+' · 关联项目 <a href="#projects">全部项目</a></div>':''}<div class="toolbar project-toolbar"><div class="filter-tabs" aria-label="筛选项目">${[['lab','全部项目'],['participating','我参与的'],['blocked','需要协助'],['archived','已归档']].map(([key,label])=>button(label,()=>go('projects',{filter:key}),filter===key?'active':'')).join('')}</div><input class="search" id="project-search" aria-label="搜索项目" placeholder="搜索项目、部门或负责人"><div class="project-actions">${me.user.role==='admin'?`<details class="project-more"><summary>更多</summary><div class="project-more-panel">${button('预览协同表',()=>importPreview(),'quiet-button')}${button('人员部门',()=>editDepartment(),'quiet-button')}</div></details>`:''}${button('创建项目 ＋',()=>projectForm(),'primary')}</div></div><div id="project-table"></div>`);
 const paint=q=>document.querySelector('#project-table').innerHTML=projectTable(projects.filter(p=>(filter==='archived'?p.status==='archived':p.status!=='archived'&&((filter==='lab'||filter==='all')&&p.ownerTeam==='AI创新实验室'||filter==='participating'&&p.member||filter==='blocked'&&p.status==='blocked'))&&(!route().repository||(projects.some(x=>x.repository?.fullName===route().repository)?p.repository?.fullName===route().repository:p.repository?.familyNames?.includes(route().repository)))&&[p.name,p.department,ownerLabel(p)].some(x=>x.toLowerCase().includes(q.toLowerCase()))));
 const more=document.querySelector('.project-more');
 more?.addEventListener('click',event=>{if(event.target.closest('button'))more.open=false;});
 more?.addEventListener('focusout',event=>{if(!more.contains(event.relatedTarget))more.open=false;});
 more?.addEventListener('keydown',event=>{if(event.key==='Escape'){more.open=false;more.querySelector('summary').focus();}});
 const search=document.querySelector('#project-search');
 const returning=projectListReturn?.hash===(location.hash||'#projects')?projectListReturn:null;
 if(returning){search.value=returning.query;requestAnimationFrame(()=>window.scrollTo(0,returning.scroll));projectListReturn=null;}
 paint(search.value);search.oninput=ev=>paint(ev.target.value);
}
function openListedProject(id){
 projectListReturn={id,hash:location.hash||'#projects',query:document.querySelector('#project-search')?.value||'',scroll:window.scrollY};
 projectGo(id);
}
function projectTable(rows){return rows.length?`<div class="table-wrap project-table"><table><thead><tr><th>项目</th><th>状态</th><th>任务进度</th><th>负责团队</th><th>下一节点</th></tr></thead><tbody>${rows.map(p=>{const done=Math.max(0,Number(p.completed)||0),total=Math.max(done,Number(p.total)||0);return `<tr class="click-row" tabindex="0" aria-label="打开项目：${e(p.name)}" data-action="${on(()=>p.member?openListedProject(p.id):showSummary(p))}"><td class="title">${p.confidential?'<span class="pin">保密</span> ':''}<strong class="project-name">${e(p.name)}</strong><small class="project-summary">${e(plain(p.summary||p.goal))}</small><div class="project-mobile-summary"><div>${badge(p.status)}<span>${done} / ${total} 项完成</span></div><small>下一节点 · ${e(p.nextTitle||'待安排')}</small></div></td><td>${badge(p.status)}</td><td><div class="project-progress"><progress value="${done}" max="${Math.max(1,total)}" aria-label="${done} / ${total} 项任务完成"></progress><span>${done} / ${total}</span></div></td><td>${teamOwner(p)}</td><td class="next-node">${e(p.nextTitle||'待安排')}<small>${p.nextDue?'计划 '+e(p.nextDue):'日期待安排'}</small></td></tr>`;}).join('')}</tbody></table></div>`:empty('没有符合条件的项目。');}
function showSummary(p){modal(p.name,`<dl class="meta"><dt>负责人</dt><dd>${teamOwner(p)}</dd><dt>目标</dt><dd>${rich(p.goal)}</dd><dt>最新概况</dt><dd>${rich(p.summary)||'待补充'}</dd></dl>${button('申请参与',async()=>{await api(`/projects/${p.id}/join-requests`,'POST',{});dialog.close();toast(p.ownerId?'已通知负责人':'已通知管理员处理参与申请');},'primary')}`);}
function projectForm(p=null){modal(p?'编辑项目':'创建项目',`<form><div class="form-grid">${field('项目名称','name',p?.name,'text',true)}${field('涉及部门','department',p?.department)}${field('负责团队','ownerTeam',p?.ownerTeam||'AI创新实验室')}${textField('为什么做','goal',p?.goal)}${textField('怎么做','approach',p?.approach)}${textField('公开进度摘要','summary',p?.summary)}${selectField('可见范围','confidential',[['false','普通项目：全员看概况'],['true','保密项目：仅成员可见']],String(p?.confidential||false))}${p?selectField('总体状态','status',['planned','active','blocked','completed','archived'].map(s=>[s,labels[s]]),p.status):'<p class="muted">创建后你将成为项目负责人，可随时添加同事。</p>'}${formEnd()}`);const form=dialog.querySelector('form');mentions(form,p?.id);bindForm(async(v,f)=>{const data={...v,goal:encodeMentions(f,'goal',v.goal),approach:encodeMentions(f,'approach',v.approach),summary:encodeMentions(f,'summary',v.summary),confidential:v.confidential==='true',revision:p?.revision||0,status:v.status||'planned'};const result=await api('/projects'+(p?'/'+p.id:''),p?'PUT':'POST',data);dialog.close();projectGo(result.id);});}
async function projectPage(r){const p=current.project,code=['code','development','releases'].includes(r.tab),dev=await api(`/projects/${p.id}/development`+(r.repositoryId?'?repositoryId='+encodeURIComponent(r.repositoryId):''));current.development=dev;developmentFingerprint=JSON.stringify(dev);developmentNext=performance.now()+developmentDelay(dev);if(code&&dev.repository){const catalog=await api(`/projects/${p.id}/code/catalog`),repo=catalog.repositories.find(x=>x.id===(r.repositoryId||dev.repository.id));if(!repo)throw Error('代码库不属于本项目');codeState={...catalog,repo,reference:r.ref||repo.mainBranch,section:r.section||'files',path:r.path||''};}
 const intro=`<details class="project-about"><summary>项目简介<span>${e(plain(p.goal)||'补充目标与推进方案')}</span></summary><div><h3>项目目标</h3><p>${rich(p.goal)||'项目目标待补充'}</p>${p.approach?'<h3>推进方案</h3><p>'+rich(p.approach)+'</p>':''}${p.summary?'<h3>最新概况</h3><p>'+rich(p.summary)+'</p>':''}<div class="intro-meta"><span>${e(p.department||'部门待补充')}</span>${current.canManage?button('编辑简介',()=>projectForm(p),'text-button'):''}</div></div></details>`;
 shell(`<div class="project-heading"><div class="project-title"><a href="${e(projectListReturn?.id===p.id?projectListReturn.hash:'#projects')}" aria-label="返回项目列表">←</a><h1>${e(p.name)}</h1>${badge(p.status)}</div><div class="project-heading-meta">${teamOwner(p)}${button('协作者 · '+current.members.length,()=>membersDialog(),'text-button')}</div></div><div class="tabs">${[['tasks','任务'],['code','代码库']].map(([tab,title])=>button(title,()=>projectGo(p.id,tab),'tab '+((code?'code':'tasks')===tab?'active':''))).join('')}</div>`+intro+(code?codeView(dev):tasksView()));
 if(!code)bindTaskViews();
 if(code&&dev.repository){bindCodeSelectors();await loadCodeSection();}
 if(r.target){const action=current.actions.find(a=>a.id===r.target)||current.actions.find(a=>current.progress.some(x=>x.id===r.target&&x.actionId===a.id));if(action)await actionDetail(action);else {
  const task=current.tasks.find(t=>t.id===r.target);if(task){taskDetail(task);return;}
  const item=document.getElementById('item-'+r.target);
  for(let details=item?.closest('details');details;details=details.parentElement?.closest('details'))details.open=true;
  item?.scrollIntoView({block:'center'});
 }}
}
function membersDialog(){modal('项目协作者',`<div class="member-list">${current.members.map(m=>`<div class="file-row">${person(m.staffId)}<small>${m.role==='owner'?'负责人':'协作者'}</small>${current.canManage&&m.role!=='owner'?button('管理',()=>manageMember(m)):''}</div>`).join('')||empty('尚未添加具体协作者')}</div>${button('添加协作者',()=>invite(),'primary')}`);}
const repositoryTitles={"siyue-miniapp-accounts": "账号与权限", "siyue-miniapp-printing": "错题与文件打印", "siyue-miniapp-devices": "打印设备与客户端", "siyue-miniapp-attendance": "课堂考勤", "siyue-miniapp-homework": "作业发布收集与批改", "siyue-miniapp-question-bank": "题库与错题强化", "siyue-miniapp-research": "教研与讲义", "siyue-miniapp-teaching": "教学辅助与学情", "siyue-miniapp-students": "班级与学员档案", "siyue-miniapp-parents": "家长查看与反馈", "siyue-miniapp-operations": "学部运营与活动", "siyue-miniapp-outreach": "招生与学情诊断", "siyue-miniapp-analytics": "使用统计与管理看板", "siyue-miniapp-feedback": "意见反馈", "siyue-miniapp-collaboration": "项目协作", "siyue-wrong-question-miniapp": "错题打印小程序", "siyue-crm": "思跃 CRM", "siyue-information-workbench": "信息采集台", "siyue-operations-calendar": "学部微信群运营日历", "siyue-admissions-scheduling": "招生排课", "siyue-wecom-assistant": "思小跃企业微信助手"};
const repositoryTitle=r=>repositoryTitles[r.name]||r.name;
function codeArgs(extra={}){return new URLSearchParams({repositoryId:codeState.repo.id,reference:codeState.reference,...extra}).toString();}
function codeApi(path,extra={}){return `/projects/${current.project.id}/code/${path}?`+codeArgs(extra);}
function codeNavigate(extra={}){projectGo(current.project.id,'code','table',{repositoryId:codeState.repo.id,ref:codeState.reference,section:codeState.section,...extra});}
function codeView(d){if(!d.repository)return `<div class="panel">${empty('尚未关联源码。由管理员关联后，即可在项目内浏览和提交修改。')}${me.user.role==='admin'?button('关联代码库',()=>repositoryForm(),'primary'):''}</div>`;
 const r=codeState.repo,primary=r.id===current.project.repositoryId;
 return `<section class="repository-heading"><div><h2>${e(repositoryTitle(r))}</h2><p class="prototype-credit">${r.parentRepositoryId?'主项目原型作者':'原型作者'}：${e(r.prototypeAuthor||'待补充')}</p>${r.parentRepositoryId?button('← 错题打印小程序主仓库',()=>codeNavigate({repositoryId:r.parentRepositoryId,ref:'main',section:'files'}),'text-button'):''}<p class="muted">${r.automationEnabled?'修改检查通过后，由负责人验收、管理员发布。':'源码已托管，自动检查与部署尚未启用。'}</p></div><div class="actions">${button('交给 Workbuddy',()=>agentDialog(pickProjectId()),'primary')}${button('复制仓库地址',()=>copyText(me.codeUrl.replace(/\/$/,'')+'/'+r.fullName+'.git'))}</div></section><div class="code-controls">${codeState.repositories.length>1?selectField('代码模块','code-repository',codeState.repositories.map(x=>[x.id,(x.parentRepositoryId?'模块 · ':'主仓库 · ')+repositoryTitle(x)]),r.id):''}${selectField('分支 / 版本','code-branch',[[codeState.reference,codeState.reference]],codeState.reference)}<div id="branch-more"></div></div><div class="code-sections" role="navigation" aria-label="仓库内容">${[['files','源码'],['commits','提交记录'],['pulls','修改申请']].map(([key,label])=>button(label,()=>codeNavigate({section:key,path:''}),codeState.section===key?'active':'')).join('')}${primary?button('提交文件修改',()=>fileForm(),'quiet-button'):''}${button('新建修改申请',()=>pullForm(),'quiet-button')}</div>${primary?'<div class="code-task-links"><span>关联任务</span>'+current.tasks.map(t=>button(e(t.title),()=>taskForm(t),'text-button')).join('')+'</div>':''}<div id="code-content"></div><section class="repository-delivery">${developmentView(d)}${primary?'<details><summary>验收与正式发布</summary>'+releasesView(d)+'</details>':''}</section>`;
}
async function bindCodeSelectors(){const select=document.querySelector('[name=code-repository]');if(select)select.onchange=ev=>codeNavigate({repositoryId:ev.target.value,ref:codeState.repositories.find(r=>r.id===ev.target.value).mainBranch,section:'files',path:''});document.querySelector('[name=code-branch]').onchange=ev=>codeNavigate({ref:ev.target.value,path:''});await loadBranches(1);}
async function loadBranches(page){const rows=await api(codeApi('branches',{page})),select=document.querySelector('[name=code-branch]');if(!select)return;for(const row of rows.items)if(![...select.options].some(x=>x.value===row.name)){const option=document.createElement('option');option.value=row.name;option.textContent=row.name;select.append(option);}document.querySelector('#branch-more').innerHTML=rows.hasMore?button('更多分支',()=>loadBranches(page+1),'text-button'):'';}
async function loadCodeSection(){if(codeState.section==='pulls')return loadPulls();if(codeState.section==='commits')return loadCommits();return loadCodeTree(codeState.path);}
async function loadCodeTree(path){const data=await api(codeApi('tree',{path})),parent=path.split('/').slice(0,-1).join('/');document.querySelector('#code-content').innerHTML=`<div class="code-path">${path?button('← 上一级',()=>codeNavigate({path:parent}),'text-button'):''}<span>${e(path||'/')}</span></div><div class="table-wrap"><table class="code-tree"><tbody>${data.map(f=>`<tr class="click-row" tabindex="0" data-action="${on(()=>f.moduleRepositoryId?codeNavigate({repositoryId:f.moduleRepositoryId,ref:f.sha,section:'files',path:''}):f.type==='dir'?codeNavigate({path:f.path}):viewCode(f))}" aria-label="打开 ${e(f.name)}"><td>${f.type==='dir'?'▸':f.moduleRepositoryId?'⌘':'·'} ${e(f.name)}</td><td>${f.moduleRepositoryId?'固定模块版本 '+e(f.sha.slice(0,8)):f.type==='dir'?'文件夹':(f.size/1024).toFixed(1)+' KB'}</td></tr>`).join('')}</tbody></table></div>`;}
async function loadCommits(page=1,path=codeState.path||'',inDialog=false){const data=await api(codeApi('commits',{page,path}));const html=`${path?'<p>文件：'+e(path)+'</p>':''}<div class="code-history">${data.items.map(x=>button(`<strong>${e(x.message.split('\n')[0])}</strong><small>${e(x.author)} · ${date(x.date)} · ${e(x.sha.slice(0,12))}</small>`,()=>commitDetail(x.sha),'commit-row')).join('')||empty('此版本暂无提交记录')}</div><div class="actions">${page>1?button('上一页',()=>loadCommits(page-1,path,inDialog)):''}${data.hasMore?button('下一页',()=>loadCommits(page+1,path,inDialog)):''}</div>`;if(inDialog)modal('提交记录',html);else document.querySelector('#code-content').innerHTML=html;}
function diffHtml(diff,truncated){return `${truncated?'<p class="notice">差异超过512KB，当前只显示前半部分；可交给本地 Agent 读取完整差异。</p>':''}<pre class="source-diff">${diff.split('\n').map(line=>'<span class="'+(line.startsWith('+')?'diff-add':line.startsWith('-')?'diff-remove':line.startsWith('@@')?'diff-hunk':'')+'">'+e(line)+'\n</span>').join('')}</pre>`;}
async function commitDetail(sha){const d=await api(codeApi('commits/'+encodeURIComponent(sha)));modal('提交 '+sha.slice(0,12),`<p>${e(d.message)}</p><p class="muted">${e(d.author)} · ${date(d.date)}</p>${diffHtml(d.diff,d.truncated)}`);}
async function loadPulls(page=1){const d=await api(codeApi('pulls',{page,state:'all'}));document.querySelector('#code-content').innerHTML=`<div class="change-list">${d.items.map(x=>`<article><div>${button('#'+x.number+' '+e(x.title),()=>pullDetail(x.number),'text-button change-title')}<p>${e(x.author.name||gitActor(x.author.login))} · ${e(x.head)} → ${e(x.base)} · ${date(x.updatedAt)}</p></div>${badge(x.state)}</article>`).join('')||empty('还没有修改申请。提交任务分支后，可直接在这里创建。')}</div><div class="actions">${page>1?button('上一页',()=>loadPulls(page-1)):''}${d.hasMore?button('下一页',()=>loadPulls(page+1)):''}</div>`;}
async function pullDetail(number){const d=await api(codeApi('pulls/'+number)),p=d.pull,passed=d.checks.some(x=>x.context==='siyue/ci'&&x.state==='success');modal('#'+number+' '+p.title,`<div class="row">${badge(p.state)}<span>${e(p.head)} → ${e(p.base)}</span><span class="version-id">${e(p.sha.slice(0,12))}</span></div><p class="pull-description">${e(p.body)}</p><div class="code-checks"><h3>当前提交检查</h3>${d.checks.map(x=>'<p>'+e(x.context)+' · '+e(x.state)+' · '+e(x.description)+'</p>').join('')||'<p class="muted">尚无检查结果</p>'}${!d.automationEnabled?'<p class="muted">此仓库自动检查尚未启用，暂不能合并。</p>':''}</div>${p.state==='open'?'<div class="actions">'+button('评论 / 审核',()=>reviewForm(p))+(current.canManage&&d.automationEnabled&&passed&&p.mergeable?button('合并到主分支',()=>mergeConfirm(p),'primary'):'')+'</div>':''}<details open class="pull-diff"><summary>代码差异</summary>${diffHtml(d.diff,d.truncated)}</details><section><h3>审核记录</h3>${d.reviews.map(r=>'<article class="action-comment"><div>'+e(r.author.name||gitActor(r.author.login))+' · '+e(({APPROVED:'同意',REQUEST_CHANGES:'需要修改',COMMENT:'评论'})[r.state]||r.state)+' · '+date(r.date)+'</div><p>'+e(r.body)+'</p><small>审核版本 '+e(r.sha.slice(0,12))+'</small></article>').join('')||'<p class="muted">暂无审核记录</p>'}<p class="muted tiny">展示最近50条审核记录。</p></section>`);}
async function pullForm(){modal('新建修改申请',`<form><div class="form-grid">${field('标题','title','','text',true)}${field('开发分支','head',codeState.reference===codeState.repo.mainBranch?'':codeState.reference,'text',true)}${selectField('关联任务','taskId',[['','不关联任务'],...(codeState.repo.id===current.project.repositoryId?current.tasks.map(t=>[t.id,t.title]):[])],'')}${textField('修改说明与测试结果','body','')}<p class="field full muted">合并目标：${e(codeState.repo.mainBranch)}。选择任务后，开发分支为 task/任务编号。</p>${formEnd('创建修改申请')}`);dialog.querySelector('[name=taskId]').onchange=ev=>{if(ev.target.value)dialog.querySelector('[name=head]').value='task/'+ev.target.value;};bindForm(async v=>{const r=await api(codeApi('pulls'),'POST',{...v,taskId:v.taskId||null});await pullDetail(r.number);});}
function reviewForm(p){modal('评论 / 审核 #'+p.number,`<form><div class="form-grid">${selectField('意见','event',[['COMMENT','评论'],['APPROVED','同意修改'],['REQUEST_CHANGES','需要修改']],'COMMENT')}${textField('具体意见','body','',true)}<p class="field full muted">审核版本 ${e(p.sha.slice(0,12))}</p>${formEnd('提交意见')}`);bindForm(async v=>{await api(codeApi('pulls/'+p.number+'/reviews'),'POST',{...v,headSha:p.sha});await pullDetail(p.number);});}
function mergeConfirm(p){modal('合并修改申请',`<p>#${p.number} ${e(p.title)}</p><p>将 ${e(p.sha.slice(0,12))} 合并到 ${e(p.base)}。合并通过受保护分支检查，不会发布正式网址。</p>${button('确认合并这个版本',async()=>{await api(codeApi('pulls/'+p.number+'/merge'),'POST',{headSha:p.sha});await pullDetail(p.number);},'primary')}`);}
function fileForm(content=null){if(codeState.repo.id!==current.project.repositoryId){toast('请回到项目关联的模块提交修改');return;}modal(content?'编辑并提交文件':'提交文件修改',`<form><div class="form-grid">${field('文件路径','path',content?.path||'','text',true)}${selectField('关联开发任务','taskId',current.tasks.map(t=>[t.id,t.title]),'')}${field('提交说明','message','','text',true)}<label class="field full">文本文件内容<textarea name="content" rows="16" class="source-editor">${e(content?.content||'')}</textarea></label>${!content?'<label class="field full">或从电脑读取文本文件<input id="source-upload" type="file"></label>':''}<p class="field full muted">保存到所选任务的开发分支，不直接修改主分支。提交后可在本页创建修改申请。</p>${formEnd('提交到任务分支')}`);const upload=dialog.querySelector('#source-upload');if(upload)upload.onchange=ev=>void run(async()=>{const f=ev.target.files[0];if(!f)return;if(f.size>524288)throw Error('文本文件请控制在512KB以内');const bytes=await f.arrayBuffer();if(new Uint8Array(bytes).includes(0))throw Error('请选择文本源码文件');const text=new TextDecoder('utf-8',{fatal:true}).decode(bytes);dialog.querySelector('[name=content]').value=text;if(!dialog.querySelector('[name=path]').value)dialog.querySelector('[name=path]').value=f.name;});bindForm(async v=>{const result=await api(`/projects/${current.project.id}/code/files`,'POST',{...v,sha:content?.sha||null,branch:content?.branch||null});dialog.close();codeNavigate({ref:result.branch,section:'files',path:''});toast('已提交到任务分支，可新建修改申请');});}

function invite(){choosePerson('添加协作者',async p=>{await api(`/projects/${current.project.id}/members`,'POST',{staffId:p.id});dialog.close();await render();toast('已加入项目并发送站内通知');});}
function manageMember(m){modal('管理 '+name(m.staffId),`<p class="muted">移出项目将同时撤销项目访问和代码权限。</p><div class="actions">${button('移交负责人',async()=>{await api(`/projects/${current.project.id}/owner`,'POST',{staffId:m.staffId});dialog.close();await render();})}${button('移出项目',async()=>{await api(`/projects/${current.project.id}/members/${m.staffId}`,'DELETE');dialog.close();await render();},'danger')}</div>`);}
const taskStates=['planned','in_progress','blocked','review','done'];
const taskViewNames={list:'列表',board:'看板',table:'协作表'};
function selectedTaskView(){return Object.hasOwn(taskViewNames,route().view)?route().view:'list';}
function taskOptions(extra={}){return {...(route().scope==='mine'?{scope:'mine'}:{}),q:document.querySelector('#task-search')?.value??route().q??'',status:document.querySelector('#task-status')?.value??route().status??'',...extra};}
function taskViewButton(key){const selected=selectedTaskView()===key;return `<button type="button" class="${selected?'active':''}" aria-pressed="${selected}" data-action="${on(()=>projectGo(current.project.id,'tasks',key,taskOptions()))}">${taskViewNames[key]}</button>`;}
function tasksView(){const mine=route().scope==='mine';return `<section class="task-workspace"><div class="task-toolbar"><input class="search" id="task-search" type="search" value="${e(route().q||'')}" aria-label="搜索任务或节点" placeholder="搜索任务、节点或负责人"><select id="task-status" aria-label="筛选任务状态"><option value="">全部状态</option>${taskStates.map(state=>`<option value="${state}" ${route().status===state?'selected':''}>${labels[state]}</option>`).join('')}</select>${button(mine?'与我有关 · 已选':'与我有关',()=>projectGo(current.project.id,'tasks',selectedTaskView(),taskOptions({scope:mine?'all':'mine'})),'task-scope '+(mine?'active':''))}<div class="view-switch" role="group" aria-label="任务视图">${Object.keys(taskViewNames).map(taskViewButton).join('')}</div>${button('新建任务',()=>taskForm(),'primary')}</div><div class="task-result-summary" id="task-result-summary" aria-live="polite"></div><div id="task-content"></div></section>`;}
function bindTaskViews(){document.querySelector('#task-search').oninput=paintTasks;document.querySelector('#task-status').onchange=paintTasks;paintTasks();}
function relatedToMe(t){let collaborators=[];try{collaborators=JSON.parse(t.collaborators||'[]');}catch{}return t.ownerId===me.user.id||t.needsStaffId===me.user.id||collaborators.includes(me.user.id);}
function taskMatches(t,q){return !q||[t.title,t.description,t.criteria,t.blocker,t.ownerId?name(t.ownerId):ownerLabel(current.project),...(current.actions||[]).filter(a=>a.taskId===t.id).flatMap(a=>[a.title,a.body])].some(value=>plain(value).toLowerCase().includes(q));}
function paintTasks(){for(const node of document.querySelectorAll('#task-content [data-action]'))handlers.delete(node.dataset.action);const q=(document.querySelector('#task-search')?.value||'').trim().toLowerCase(),state=document.querySelector('#task-status')?.value||'',mine=route().scope==='mine';const tasks=current.tasks.filter(t=>(!mine||relatedToMe(t))&&(!state||t.state===state)&&taskMatches(t,q));const taskIds=new Set(tasks.map(t=>t.id));const actions=(current.actions||[]).filter(a=>a.taskId?taskIds.has(a.taskId):!mine&&(!state||a.state===state)&&(!q||[a.title,a.body].some(value=>plain(value).toLowerCase().includes(q))));const view=selectedTaskView();document.querySelector('#task-result-summary').textContent=`${tasks.length} 项任务 · ${actions.length} 个推进节点`;document.querySelector('#task-content').innerHTML=view==='table'?taskTimeline(tasks,actions,mine):(view==='board'?taskBoard(tasks):taskList(tasks))+projectRecords(actions.filter(a=>!a.taskId));}
function taskNodeCount(t){return (current.actions||[]).filter(a=>a.taskId===t.id).length;}
function taskDue(t){return t.dueOn?'截止 '+e(t.dueOn):'未设截止日期';}
function taskList(tasks){return tasks.length?`<div class="task-list" role="list">${tasks.map(t=>`<div role="listitem" id="item-${t.id}">${button(`<span class="state-dot ${e(t.state)}" aria-label="${labels[t.state]||t.state}"></span><span class="task-row-title"><strong>${e(t.title)}</strong><small>${e(plain(t.description||t.blocker||''))}</small></span><span class="task-row-state">${badge(t.state)}</span><span class="task-row-owner">${taskOwner(t)}</span><span class="task-row-due">${taskDue(t)}</span><span class="task-row-nodes">${taskNodeCount(t)} 节点</span>`,()=>taskDetail(t),'task-row')}</div>`).join('')}</div>`:empty('没有符合条件的任务。');}
function taskBoard(tasks){return `<div class="task-board" aria-label="按状态查看任务">${taskStates.map(state=>{const rows=tasks.filter(t=>t.state===state);return `<section class="task-column" data-state="${state}"><h3><span class="state-dot ${state}" aria-hidden="true"></span>${labels[state]}<span class="task-column-count">${rows.length}</span></h3><div class="task-column-items">${rows.map(t=>`<div id="item-${t.id}">${button(`<strong>${e(t.title)}</strong>${t.blocker?'<span class="task-blocker">'+e(plain(t.blocker))+'</span>':t.description?'<span class="task-card-description">'+e(plain(t.description))+'</span>':''}<span class="task-card-footer">${taskOwner(t)}<span>${taskNodeCount(t)} 节点</span></span><small>${taskDue(t)}</small>`,()=>taskDetail(t),'task-card')}</div>`).join('')||'<p class="task-column-empty">暂无任务</p>'}</div></section>`;}).join('')}</div>`;}
function projectRecords(actions){return actions.length?`<details class="project-records" open><summary>项目推进记录 <span>${actions.length}</span></summary><div class="project-record-cards">${actions.map(actionCard).join('')}</div></details>`:'';}
function taskTimeline(tasks,allActions,mine){const buckets=[...new Set(allActions.map(a=>a.plannedOn||a.dateLabel||'待安排'))].sort((a,b)=>{const rank=x=>x==='待安排'?0:/^\d{4}-/.test(x)?1:2;return rank(a)-rank(b)||a.localeCompare(b);});if(!buckets.length)buckets.push('待安排');const rows=[...tasks,...(!mine&&allActions.some(a=>!a.taskId)?[null]:[])];return `<div class="table-wrap action-grid"><table><thead><tr><th class="task-col">任务</th><th class="owner-col">负责人</th>${buckets.map(key=>'<th>'+e(key)+'</th>').join('')}<th class="add-col"></th></tr></thead><tbody>${rows.map(t=>`<tr id="item-${t?.id||'project'}"><td class="task-col">${t?button(e(t.title),()=>taskDetail(t),'text-button task-title'):'项目推进记录'}${t?'<div class="task-state">'+badge(t.state)+'</div>':''}${t?.blocker?'<small class="blocker-note">'+rich(t.blocker)+'</small>':''}</td><td class="owner-col">${taskOwner(t)}</td>${buckets.map(key=>`<td class="actions-cell">${allActions.filter(a=>a.taskId===(t?.id||null)&&(a.plannedOn||a.dateLabel||'待安排')===key).map(actionCard).join('')||'<span class="empty-cell">—</span>'}</td>`).join('')}<td class="add-col">${button('＋',()=>actionForm(null,t?.id||null),'add-action')}</td></tr>`).join('')||'<tr><td colspan="'+(buckets.length+3)+'">还没有任务，可新建任务后记录推进节点。</td></tr>'}</tbody></table></div>`;}
function taskDetail(t){t=current.tasks.find(item=>item.id===t.id)||t;const actions=(current.actions||[]).filter(a=>a.taskId===t.id);modal(t.title,`<div class="task-detail-properties">${badge(t.state)}${taskOwner(t)}<span>${taskDue(t)}</span>${t.startsOn?'<span>开始 '+e(t.startsOn)+'</span>':''}</div><div class="actions task-detail-actions">${button('编辑任务',()=>taskForm(t),'text-button')}${button('添加节点',()=>actionForm(null,t.id),'primary')}${button('复制给 Agent',async()=>{const result=await api(`/projects/${current.project.id}/tasks/${t.id}/agent`);await copyText(result.text);},'text-button')}</div><section class="task-detail-section"><h3>需求说明</h3><p>${rich(t.description)||'尚未填写需求说明。'}</p></section>${t.criteria?'<section class="task-detail-section"><h3>验收标准</h3><p>'+rich(t.criteria)+'</p></section>':''}${t.blocker?'<section class="task-detail-section"><h3>阻塞事项</h3><p>'+rich(t.blocker)+'</p></section>':''}<section class="task-detail-section"><h3>推进节点 <span>${actions.length}</span></h3><div class="task-detail-nodes">${actions.map(actionCard).join('')||'<p class="muted">还没有推进节点。</p>'}</div></section>`,{drawer:true});}
function actionCard(a){const comments=current.progress.filter(x=>x.actionId===a.id&&!x.requestId.startsWith('csv:')).length;return button(`<span class="action-date">${a.kind==='code'?'代码仓库':'节点动作'}</span><strong>${e(a.title)}</strong><small>${e(plain(a.body).slice(0,100))}</small><span class="action-meta">${badge(a.state)}${comments?'<span>'+comments+' 条评论</span>':''}</span>`,()=>actionDetail(a),'action-card');}
function actionForm(a=null,taskId=null){const d=current.development;modal(a?'编辑节点动作':'添加节点动作',`<form><div class="form-grid">${field('动作名称','title',a?.title,'text',true)}${selectField('状态','state',['planned','in_progress','blocked','review','done'].map(x=>[x,labels[x]]),a?.state||'planned')}${field('时间节点','plannedOn',a?.plannedOn,'date')}${selectField('内容类型','kind',[['update','工作动作'],...(d.repository?[['code','代码仓库 / 提交']]:[])],a?.kind||'update')}${textField('动作说明','body',a?.body)}${d.repository?field('提交编号或分支（代码动作可填）','codeRef',a?.codeRef):''}${formEnd('保存',()=>a?actionDetail(a):taskId?taskDetail(current.tasks.find(t=>t.id===taskId)):dialog.close())}`);mentions(dialog.querySelector('form'),current.project.id);const requestId=crypto.randomUUID();bindForm(async(v,f)=>{const body={...v,body:encodeMentions(f,'body',v.body),taskId:a?a.taskId:taskId,plannedOn:v.plannedOn||null,dateLabel:a?.dateLabel||'',repositoryId:v.kind==='code'?d.repository?.id:null,revision:a?.revision||0,requestId};const saved=await api(`/projects/${current.project.id}/actions`+(a?'/'+a.id:''),a?'PUT':'POST',body);dialog.close();await refreshAction(saved.id);});}
async function refreshAction(id){const detail=await api('/projects/'+current.project.id);current={...detail,development:current.development};await actionDetail(current.actions.find(a=>a.id===id));}
async function actionDetail(a){const task=current.tasks.find(t=>t.id===a.taskId),comments=current.progress.filter(x=>x.actionId===a.id&&!x.requestId.startsWith('csv:')).sort((a,b)=>a.createdAt.localeCompare(b.createdAt));const files=current.attachments.filter(x=>x.actionId===a.id);const d=a.codeRef?await api(`/projects/${current.project.id}/development`):current.development;const version=d.builds.find(b=>b.sha===a.codeRef);const ref=a.codeRef;const codeUrl=d.repository&&a.repositoryId===d.repository.id?d.codeUrl+(ref?(/^[a-f0-9]{40,64}$/i.test(ref)?'/commit/':'/src/branch/')+ref.split('/').map(encodeURIComponent).join('/'):''):null;
 function commentTree(parent=null,depth=0){if(depth>20)return '';return comments.filter(c=>c.parentId===parent).map(c=>`<article class="action-comment ${depth?'reply':''}" id="comment-${c.id}"><div class="row">${person(c.authorId)}<time>${date(c.createdAt)}</time>${button('回复',()=>commentForm(a,c),'text-button')}</div><p>${rich(c.body)}</p>${commentTree(c.id,depth+1)}</article>`).join('');}
 modal(a.title,`<div class="drawer-breadcrumb"><span>${e(current.project.name)}</span><span aria-hidden="true">/</span>${task?button(e(task.title),()=>taskDetail(task),'text-button'):'<span>项目推进记录</span>'}</div><div class="action-detail-meta">${taskOwner(task)}<span>${e(a.plannedOn||a.dateLabel||'时间待安排')}</span>${badge(a.state)}</div><div class="action-body">${rich(a.body)}</div>${codeUrl?button(e(d.repository.name)+(ref?' · '+e(ref.slice(0,12)):''),()=>{dialog.close();projectGo(current.project.id,'code','table',{ref:ref||d.repository.mainBranch,section:ref?'commits':'files'});},'text-button action-repo'):''}${version?'<div class="actions">'+badge(version.state)+(['tested','previewed'].includes(version.state)?button('体验此提交',()=>openPreview(version),'primary'):'<span class="muted">'+e(version.summary)+'</span>')+'</div>':''}<div class="actions node-tools">${button('编辑',()=>actionForm(a))}${button('提醒协作者',()=>remindForm(a))}${button('添加资料',()=>uploadForm(a))}${task&&d.repository?button('复制给 Agent',async()=>{const r=await api(`/projects/${current.project.id}/tasks/${task.id}/agent`);await copyText(r.text+'\n当前节点：'+a.id+'\n节点动作：'+a.title+'\n说明：'+a.body);}):''}</div>${files.length?'<div class="node-files">'+files.map(f=>button(e(f.name),()=>download(f),'text-button')).join('')+'</div>':''}<section class="node-comments"><div class="row"><h3>评论与回复</h3>${button('写评论',()=>commentForm(a),'text-button')}</div>${commentTree()||'<p class="muted">还没有评论</p>'}</section>`,{drawer:true});
}
function commentForm(a,parent=null){const section=dialog.querySelector('.node-comments');if(!section){void run(async()=>{await actionDetail(a);commentForm(a,parent);});return;}section.querySelector('.node-comment-form')?.remove();const form=document.createElement('form');form.className='node-comment-form';form.innerHTML=`<div class="form-grid">${parent?'<blockquote class="field full">回复 '+e(name(parent.authorId))+'：'+rich(parent.body)+'</blockquote>':''}${textField('评论内容','body','',true)}</div><div class="form-actions">${button('取消',()=>form.remove())}<button class="primary" type="submit">发送</button></div>`;section.append(form);mentions(form,current.project.id);form.querySelector('textarea').focus();const requestId=crypto.randomUUID();bindForm(async(v,f)=>{const scroll=dialog.querySelector('.dialog-content').scrollTop;await api(`/projects/${current.project.id}/progress`,'POST',{body:encodeMentions(f,'body',v.body),next:'',taskId:a.taskId,actionId:a.id,parentId:parent?.id||null,requestId});await refreshAction(a.id);dialog.querySelector('.dialog-content').scrollTop=scroll;toast('评论已保存');});}
function remindForm(a){modal('提醒协作者',`<form><div class="form-grid">${selectField('提醒谁','staffId',memberOptions(),'')}${textField('提醒内容','message',a.title)}${formEnd('发送站内提醒',()=>actionDetail(a))}`);if(!current.members.length){dialog.querySelector('form').innerHTML=empty('先添加协作者，再发送节点提醒。')+button('添加协作者',()=>invite(),'primary');return;}const requestId=crypto.randomUUID();bindForm(async v=>{await api(`/projects/${current.project.id}/actions/${a.id}/remind`,'POST',{staffIds:[v.staffId],message:v.message,requestId});await actionDetail(a);toast('已发送站内提醒');});}

function taskForm(t=null,kind='task'){modal(t?'任务详情':'添加'+(kind==='milestone'?'节点':'任务'),`<form><div class="form-grid">${field('名称','title',t?.title,'text',true)}${selectField('负责人','ownerId',[['',current.project.ownerTeam||'待补充'],...memberOptions()],t?(t.ownerId||''):(current.members.some(m=>m.staffId===me.user.id)?me.user.id:''))}${selectField('状态','state',['planned','in_progress','blocked','review','done'].map(s=>[s,labels[s]]),t?.state||'planned')}${field('计划开始','startsOn',t?.startsOn,'date')}${field('计划完成','dueOn',t?.dueOn,'date')}${selectField('需要谁协助','needsStaffId',[['','暂无'],...memberOptions()],t?.needsStaffId||'')}${textField('需求说明','description',t?.description)}${textField('验收标准','criteria',t?.criteria)}${textField('阻塞原因','blocker',t?.blocker)}<label class="field full">任务协作者<select name="collaborators" multiple size="3">${memberOptions().map(([id,n])=>`<option value="${id}" ${JSON.parse(t?.collaborators||'[]').includes(id)?'selected':''}>${e(n)}</option>`).join('')}</select></label>${formEnd('保存',()=>t?taskDetail(t):dialog.close())}`+(t?`<div class="actions">${button('复制给 Agent',async()=>{const r=await api(`/projects/${current.project.id}/tasks/${t.id}/agent`);await copyText(r.text);})}${button('添加节点动作',()=>actionForm(null,t.id))}</div>`:''));mentions(dialog.querySelector('form'),current.project.id);bindForm(async(v,f)=>{const body={...v,kind:t?.kind||'task',ownerId:v.ownerId||null,description:encodeMentions(f,'description',v.description),criteria:encodeMentions(f,'criteria',v.criteria),blocker:encodeMentions(f,'blocker',v.blocker),milestoneId:t?.milestoneId||null,needsStaffId:v.needsStaffId||null,startsOn:v.startsOn||null,dueOn:v.dueOn||null,collaborators:[...f.elements.collaborators.selectedOptions].map(o=>o.value),revision:t?.revision||0};await api(`/projects/${current.project.id}/tasks`+(t?'/'+t.id:''),t?'PUT':'POST',body);dialog.close();await render();});}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('已复制');}catch{modal('复制给 Agent',`<textarea rows="16" readonly>${e(text)}</textarea>`);}}
function uploadForm(a){modal('添加节点资料',`<form><div class="form-grid"><label class="field full">选择资料<input name="file" type="file" required accept=".png,.jpg,.jpeg,.webp,.pdf,.docx,.xlsx,.csv,.txt,.md,.zip"></label><input type="hidden" name="actionId" value="${a.id}">${formEnd('上传',()=>actionDetail(a))}`);bindForm(async(_,f)=>{await api(`/projects/${current.project.id}/attachments`,'POST',new FormData(f));await refreshAction(a.id);});}

async function download(f){const response=await fetch(base+`/projects/${current.project.id}/attachments/${f.id}`,{headers:{Authorization:'Bearer '+token()}});if(!response.ok)throw Error('无法下载附件，请检查项目权限');const url=URL.createObjectURL(await response.blob());const a=document.createElement('a');a.href=url;a.download=f.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function gitActor(login){const p=people.find(p=>'staff_'+p.id.replaceAll('-','')===login);return p?.name||(login==='reconciler'?'版本核对':login);}
function developmentView(d){
 if(!d.repository)return `<div class="panel">${empty('业务协作可以直接开始。需要开发代码时，再由管理员绑定代码库。')}${me.user.role==='admin'?button('绑定代码库',()=>repositoryForm(),'primary'):''}</div>`;
 if(!d.repository.automationEnabled)return '<p class="muted">测试与正式部署需由管理员配置，上传代码不会更新正式网址。</p>';
 const repo=d.repository,p=current.project,test=d.builds.find(b=>b.id===d.testingBuildId),accepted=d.acceptances.find(a=>a.buildId===d.testingBuildId),waiting=d.builds.find(b=>b.kind==='main'&&b.id!==d.testingBuildId&&['passed','queued','running'].includes(b.state));
 return `<div class="development-intro"><p>用 Workbuddy 提交到开发分支后，自动检查并生成测试预览。合并后的版本由负责人验收，正式上线仅限管理员。</p></div>${repo.syncError?'<div class="error">'+e(repo.syncError)+'</div>':''}<div class="version-panel"><div class="version-heading"><h2>当前测试版本</h2>${test?'<span class="version-id">'+e(test.sha.slice(0,12))+'</span>':''}</div>${test?`<p class="version-state">${accepted?.passed?'负责人已验收。':accepted?'验收已退回，请根据反馈修改。':d.lockedBuildId?'已锁定，等待负责人确认验收结果。':'测试环境已更新，可以打开体验。'}${d.productionBuildId===test.id?' 此版本已正式发布。':''}</p><div class="actions">${button('体验测试版本',()=>openPreview(test),'primary')}${current.canManage&&repo.id===current.project.repositoryId?d.lockedBuildId?button('填写验收结果',()=>acceptanceForm(test))+button('解除锁定',async()=>{await api(`/projects/${p.id}/testing/unlock`,'POST',{});await render();},'quiet-button'):button('锁定版本并验收',async()=>{await api(`/projects/${p.id}/testing/lock`,'POST',{buildId:test.id,passed:false,notes:''});await render();}):''}</div><details class="version-details"><summary>查看版本凭证</summary><p class="code">提交 ${e(test.sha)}<br>产物 ${e(test.artifactDigest)}</p></details>`:empty('还没有可体验的版本。提交修改后，检查结果会显示在下方。')}${waiting?`<div class="notice">${waiting.state==='passed'&&d.lockedBuildId?'下一版本已检查通过，正在等待解除验收锁定。':'下一版本'+e(labels[waiting.state]||waiting.state)+'。'} <span class="version-id">${e(waiting.sha.slice(0,12))}</span></div>`:''}</div><div class="section-heading"><h2>修改申请 <span>${d.changes.length}</span></h2><span class="muted tiny">负责人审核，检查通过后合并</span></div><div class="change-list">${d.changes.map(x=>`<article id="item-${x.id}"><div>${button(e(x.title),()=>pullDetail(x.number),'text-button change-title')}<p>#${x.number} · ${e(gitActor(x.actor))} · ${date(x.updatedAt)}</p></div>${badge(x.state)}</article>`).join('')||empty('还没有修改申请')}</div><details class="build-history" open><summary>检查与测试预览 <span>${d.builds.length}</span></summary><div class="table-wrap"><table class="build-table"><thead><tr><th>提交版本</th><th>分支</th><th>状态</th><th>结果</th><th>时间</th></tr></thead><tbody>${d.builds.map(b=>`<tr id="item-${b.id}"><td><span class="version-id">${e(b.sha.slice(0,12))}</span></td><td class="branch-name">${e(b.branch)}</td><td>${badge(b.state)}${['previewed','tested'].includes(b.state)?button('体验此提交',()=>openPreview(b),'text-button'):''}</td><td class="build-result">${b.summary.length>140?'<details><summary>'+e(b.summary.slice(0,100))+'…</summary><pre>'+e(b.summary)+'</pre></details>':e(b.summary)}</td><td class="dates">${date(b.createdAt)}${button('检查日志',()=>buildLog(b),'text-button')}${b.state==='failed'||b.state==='passed'&&b.summary.includes('部署失败')?button(b.state==='failed'?'重新检查':'重试测试部署',async()=>{await api(`/projects/${current.project.id}/builds/${b.id}/retry`,'POST',{});await render();},'text-button'):''}</td></tr>`).join('')}</tbody></table></div></details>`;
}
async function buildLog(build){const result=await api(`/projects/${current.project.id}/builds/${build.id}/log`);modal('检查日志 · '+build.sha.slice(0,12),`<p>${e(build.branch)} · ${e(labels[build.state]||build.state)}</p>${result.truncated?'<p>日志较长，仅显示末尾256KB。</p>':''}<pre class="source-file">${e(result.text||build.summary||'任务仍在排队，暂时没有日志。')}</pre>`);}
async function openPreview(build){await api('/session','POST',{});const repositoryId=build.repositoryId;const result=await api(`/projects/${current.project.id}/preview?repositoryId=${repositoryId}&buildId=${build.id}`);modal('测试效果 · '+result.sha.slice(0,12),`<p class="notice">${e(result.notes)}</p><iframe class="project-preview" title="此提交的隔离测试环境" sandbox="allow-scripts allow-forms" referrerpolicy="no-referrer" src="${e(result.url)}"></iframe><details><summary>版本凭证</summary><p class="code">提交 ${e(result.sha)}<br>产物 ${e(result.artifactDigest)}</p></details>`);dialog.classList.add('preview-dialog');dialog.addEventListener('close',()=>dialog.classList.remove('preview-dialog'),{once:true});}
async function repositoryForm(){const repos=await api('/repositories');modal('绑定代码库',`<form><div class="form-grid">${selectField('选择代码库','existingId',[['','创建新代码库'],...repos.map(r=>[r.id,r.fullName])],'')}${field('新代码库名（英文）','name','','text')}${field('部署标识（英文）','deploymentKey','','text')}<p class="field full muted">部署标识需与管理员配置的测试环境一致。同一应用的功能项目可绑定同一代码库；保密项目使用独立代码库。</p>${formEnd()}`);bindForm(async v=>{await api(`/projects/${current.project.id}/repository`,'POST',{...v,existingId:v.existingId||null});dialog.close();await render();});}
function acceptanceForm(build){modal('验收当前版本',`<form><div class="form-grid"><p class="field full">验收版本 <span class="code">${e(build.sha.slice(0,12))}</span></p>${selectField('验收结论','passed',[['true','通过验收'],['false','退回修改']],'true')}<label class="field full">验收说明<textarea name="notes" required placeholder="记录已验证的功能、操作结果或需要修正的问题"></textarea></label>${formEnd('提交验收')}`);bindForm(async v=>{await api(`/projects/${current.project.id}/acceptances`,'POST',{buildId:build.id,passed:v.passed==='true',notes:v.notes});dialog.close();await render();});}
function releasesView(d){const p=current.project;return `<div class="toolbar"><span class="muted">正式网址只由管理员更新</span>${current.canManage&&d.testingBuildId?button('申请发布当前测试版本',()=>releaseForm(d.testingBuildId),'primary'):''}</div><div class="panel"><h3>发布记录</h3>${d.releases.map(r=>`<article class="release-card" id="item-${r.id}"><div class="row">${badge(r.state)}${r.state==='published'&&r.buildId===p.productionBuildId?'<span class="pin">当前正式版本</span>':''}<span class="muted tiny">${date(r.createdAt)}</span>${r.isRollback?'<span class="pin">回退</span>':''}</div><p>${e(r.notes)}</p><p class="muted tiny">申请人 ${e(name(r.requestedBy))}${r.publishedBy?' · 发布人 '+e(name(r.publishedBy)):''}</p><p class="muted tiny overflow">${e(r.result)}</p>${me.user.role==='admin'&&r.state==='requested'?button('核对并正式发布',()=>publishReview(r,d),'primary'):''}${me.user.role==='admin'&&r.state==='published'&&r.buildId!==p.productionBuildId?button('回退至此版本',()=>rollbackForm(r)):''}</article>`).join('')||empty('尚未发布正式版本')}</div><div class="panel"><h3>验收记录</h3>${d.acceptances.map(a=>`<div class="progress-entry">${badge(a.passed?'passed':'rejected')} <span class="code">${e(a.sha.slice(0,12))}</span><p>${e(a.notes)}</p><small class="muted">${e(name(a.staffId))} · ${date(a.createdAt)}</small></div>`).join('')||empty('尚无验收记录')}</div>`;}
function releaseForm(buildId){modal('申请正式发布',`<form><div class="form-grid"><label class="field full">更新说明<textarea name="notes" required></textarea></label>${selectField('数据库变更','databaseChanges',[['none','无数据库迁移'],['migration','涉及数据库迁移']],'none')}<label class="field full">备份与恢复方案<textarea name="recoveryPlan" placeholder="涉及数据库迁移时必填；迁移需管理员独立演练，本入口不自动执行迁移。"></textarea></label>${formEnd('提交发布申请')}`);bindForm(async v=>{await api(`/projects/${current.project.id}/releases`,'POST',{...v,buildId});dialog.close();await render();});}
function publishReview(r,d){const b=d.builds.find(x=>x.id===r.buildId);modal('核对正式发布',`<dl class="meta"><dt>更新说明</dt><dd>${e(r.notes)}</dd><dt>提交版本</dt><dd class="code">${e(b?.sha||r.buildId)}</dd><dt>产物摘要</dt><dd class="code">${e(b?.artifactDigest||'')}</dd><dt>数据库变更</dt><dd>${e(r.databaseChanges)}</dd><dt>恢复方案</dt><dd>${e(r.recoveryPlan||'使用上一已发布产物恢复')}</dd></dl><div class="notice">将发布已经验收的构建产物。健康检查失败时保留或恢复上一版本，结果会记录在本页。</div>${button('发布此版本到正式网址',async()=>{await api(`/projects/${current.project.id}/releases/${r.id}/publish`,'POST',{});dialog.close();await render();},'primary')}`);}
function rollbackForm(r){modal('回退正式版本',`<form><div class="form-grid"><label class="field full">回退原因<textarea name="notes" required></textarea></label>${formEnd('执行回退')}`);bindForm(async v=>{await api(`/projects/${current.project.id}/rollback`,'POST',{buildId:r.buildId,notes:v.notes});dialog.close();await render();});}
async function notificationPage(){const rows=await api('/notifications');rememberUnread(rows);shell(heading('站内通知','与你有关的任务、提及、测试验收和发布结果。')+`<div class="panel">${rows.map(n=>`<article class="notification ${n.readAt?'':'unread'}"><div class="content">${button(e(n.text),async()=>{await markRead(n.id);const tab=['test_ready','accepted','rejected','published','publish_failed','release_requested'].includes(n.kind)?'code':'tasks';projectGo(n.projectId,tab,'table',{target:n.targetId||''});})}<p>${date(n.createdAt)}</p></div>${!n.readAt?button('标为已读',async()=>{await markRead(n.id);await render();}):''}</article>`).join('')||empty('暂无通知')}</div>`);}
async function todoPage(){const [tasks,allProjects]=await Promise.all([api('/todos'),api('/projects')]);const projectMap=new Map(allProjects.map(p=>[p.id,p])),archived=route().archived==='1';const archivedCount=tasks.filter(t=>projectMap.get(t.projectId)?.status==='archived').length;const rows=tasks.filter(t=>(projectMap.get(t.projectId)?.status==='archived')===archived);shell(heading('我的待办','分配给你的任务，以及需要你协助的事项。')+`<div class="todo-toolbar"><div class="filter-tabs" aria-label="待办项目范围">${button('当前项目',()=>go('todos'),!archived?'active':'')}${button('已归档项目 · '+archivedCount,()=>go('todos',{archived:'1'}),archived?'active':'')}</div><span class="muted">${rows.length} 项任务</span></div><div class="todo-list">${rows.map(t=>button(`<span class="state-dot ${e(t.state)}" aria-hidden="true"></span><span class="todo-row-content"><small class="todo-project">${e(projectMap.get(t.projectId)?.name||'所属项目')}${archived?' · 已归档':''}</small><strong>${e(t.title)}</strong><small>${taskDue(t)}${t.needsStaffId===me.user.id?' · 需要你协助':''}</small></span>${badge(t.state)}`,()=>projectGo(t.projectId,'tasks','list',{target:t.id}),'todo-row')).join('')||empty(archived?'归档项目中没有待办。':'当前项目中没有待办。')}</div>`);}
function importPreview(){modal('预览协同表',`<label class="field">选择 CSV 文件<input id="csv-preview" type="file" accept=".csv"></label><div id="csv-result"></div>`);dialog.querySelector('#csv-preview').onchange=ev=>void run(async()=>{const file=ev.target.files[0];if(!file)return;if(file.size>3*1024*1024)throw Error('参考表请控制在3MB以内');const preview=previewCsv(await file.text());const used=preview.headers.map((h,i)=>[h,i]).filter(([h])=>h.trim());dialog.querySelector('#csv-result').innerHTML=`<div class="notice">${preview.rows.length} 条非空项目记录。${preview.warnings.map(e).join('<br>')}</div><div class="table-wrap"><table><thead><tr><th>原行号</th>${used.map(([h])=>'<th>'+e(h)+'</th>').join('')}</tr></thead><tbody>${preview.rows.slice(0,100).map(r=>'<tr><td>'+r.sourceRow+'</td>'+used.map(([,i])=>'<td class="title">'+e(r.cells[i]||'')+'</td>').join('')+'</tr>').join('')}</tbody></table></div>`;});}
function developmentDelay(data){
 const building=data.builds.some(build=>['queued','running'].includes(build.state));
 const publishing=data.releases.some(release=>['queued','publishing'].includes(release.state));
 return building||publishing?10000:30000;
}
async function pollDevelopment(r){
 if(pollingDevelopment||performance.now()<developmentNext)return;
 const hash=location.hash,ticket=epoch;
 pollingDevelopment=true;developmentNext=performance.now()+30000;
 try{
  const data=await api(`/projects/${r.id}/development`+(r.repositoryId?'?repositoryId='+encodeURIComponent(r.repositoryId):''));
  if(location.hash!==hash||epoch!==ticket)return;
  developmentNext=performance.now()+developmentDelay(data);
  if(JSON.stringify(data)!==developmentFingerprint&&!document.hidden&&!dialog.open&&!window.getSelection()?.toString())await render();
 }catch{}finally{pollingDevelopment=false;scheduleRefresh();}
}
function developmentPage(r){return r.page==='project'&&['code','development','releases'].includes(r.tab);}
function canRefresh(){return token()&&!document.hidden&&!dialog.open&&!root.inert;}
function scheduleRefresh(){
 clearTimeout(refreshTimer);
 if(!canRefresh())return;
 const next=unreadRequest||document.body.hasAttribute('data-platform-inbox')?[]:[unreadNext];
 if(developmentPage(route())&&!pollingDevelopment)next.push(developmentNext);
 if(next.length)refreshTimer=setTimeout(refreshVisible,Math.max(0,Math.ceil(Math.min(...next)-performance.now())));
}
function refreshVisible(){
 if(!canRefresh())return;
 const r=route();
 void unread();
 if(developmentPage(r))void pollDevelopment(r);
 scheduleRefresh();
}
window.addEventListener('hashchange',()=>void render({navigation:true}));
document.addEventListener('visibilitychange',refreshVisible);
dialog.addEventListener('close',refreshVisible);
void platformAuth.then(async auth=>{
 if(auth){
  await auth.restoreBrowserSession();
  auth.watchBrowserSession(()=>{me=null;people=[];projects=[];current=null;if(dialog.open)dialog.close();void render();});
 }
 await render();
});

function editDepartment(){choosePerson('维护人员部门',p=>{modal('维护 '+p.name+' 的部门',`<form><div class="form-grid">${field('部门','department',p.department==='待补充'?'':p.department,'text',true)}${formEnd()}`);bindForm(async v=>{await api('/people/'+p.id+'/department','PUT',v);p.department=v.department;dialog.close();toast('已更新部门，可用于搜索同事');});});}

function pickProjectId(){return current?.project.id||null;}
async function viewCode(file){const content=await api(codeApi('file',{path:file.path}));modal(file.path,`<div class="code-file-meta"><span>${e(content.branch)} · 文件版本 ${e(content.sha?.slice(0,12))}</span>${button('文件历史',()=>loadCommits(1,file.path,true),'text-button')}${codeState.repo.id===current.project.repositoryId?button('编辑文件',()=>fileForm(content),'text-button'):''}</div><pre class="source-file"><code>${e(content.content)}</code></pre>`);}

function agentDialog(selected=null){
 const url=new URL('/miniapp/workbench/workbuddy.html',location.origin);
 url.searchParams.set('module','collaboration');
 if(selected)url.searchParams.set('project',selected);
 location.assign(url);
}
